package com.nexttv;
import android.app.*;import android.content.*;import android.os.*;import android.view.KeyEvent;import android.view.accessibility.AccessibilityNodeInfo;
public class SubscriptionFixInstrumentation extends com.nexttv.support.NextTvInstrumentation {
 private boolean getArgumentsMode;private boolean singleColumn;private Activity activity;private int passed;private final StringBuilder results=new StringBuilder();
 @Override public void onCreate(Bundle b){super.onCreate(b);getArgumentsMode=b!=null&&"small".equals(b.getString("auditMode"));singleColumn=b!=null&&"true".equals(b.getString("singleColumn"));start();}

 protected void launch()throws Exception{activity=startActivitySync(new Intent(Intent.ACTION_MAIN).addCategory(Intent.CATEGORY_LAUNCHER).setClassName("com.nexttv","com.nexttv.core.tv.TvActivity").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));text("频道分类：");SystemClock.sleep(2300);}
 private void closeEditor()throws Exception{key(KeyEvent.KEYCODE_ESCAPE);SystemClock.sleep(400);if(tree().contains("保存"))key(KeyEvent.KEYCODE_ESCAPE);SystemClock.sleep(250);}
 protected void pass(String name){passed++;results.append("PASS ").append(name).append('\n');Bundle b=new Bundle();b.putString("stream","PASS "+name+"\n");sendStatus(0,b);}


 private void reopen(){try(android.os.ParcelFileDescriptor fd=getUiAutomation().executeShellCommand("am start -a android.intent.action.MAIN -c android.intent.category.LAUNCHER -f 0x10200000 -n com.nexttv/com.nexttv.core.tv.TvActivity")){java.io.FileInputStream input=new java.io.FileInputStream(fd.getFileDescriptor());byte[] buffer=new byte[1024];while(input.read(buffer)>=0){}}catch(Exception e){throw new RuntimeException(e);}}
 private void shot(String name)throws Exception{android.graphics.Bitmap image=getUiAutomation().takeScreenshot();if(image!=null){try(java.io.FileOutputStream out=new java.io.FileOutputStream(new java.io.File(getTargetContext().getFilesDir(),"fix13-"+name+".png"))){image.compress(android.graphics.Bitmap.CompressFormat.PNG,100,out);}image.recycle();}}

 private void export(String name,byte[] data,String mime,String suffix)throws Exception{String file="nexttv-audit-"+name+"-"+SystemClock.uptimeMillis()+suffix;android.content.ContentValues v=new android.content.ContentValues();v.put(android.provider.MediaStore.MediaColumns.DISPLAY_NAME,file);v.put(android.provider.MediaStore.MediaColumns.MIME_TYPE,mime);v.put(android.provider.MediaStore.MediaColumns.RELATIVE_PATH,"Download/NextTVAudit");android.net.Uri uri=getTargetContext().getContentResolver().insert(android.provider.MediaStore.Downloads.EXTERNAL_CONTENT_URI,v);try(java.io.OutputStream out=getTargetContext().getContentResolver().openOutputStream(uri)){out.write(data);}Bundle b=new Bundle();b.putString("stream","EXPORT "+file+"\n");sendStatus(0,b);}
 private String nodes(AccessibilityNodeInfo n){if(n==null)return "";android.graphics.Rect r=new android.graphics.Rect();n.getBoundsInScreen(r);String t=n.getText()==null?"":n.getText().toString();String d=n.getContentDescription()==null?"":n.getContentDescription().toString();StringBuilder b=new StringBuilder();if(!t.isEmpty()||!d.isEmpty()||n.isFocusable())b.append("text=").append(t).append(" desc=").append(d).append(" selected=").append(n.isSelected()).append(" focus=").append(n.isFocused()).append(" focusable=").append(n.isFocusable()).append(" click=").append(n.isClickable()).append(" bounds=").append(r).append('\n');for(int i=0;i<n.getChildCount();i++)b.append(nodes(n.getChild(i)));return b.toString();}
 private void record(String name)throws Exception{SystemClock.sleep(350);android.graphics.Bitmap image=getUiAutomation().takeScreenshot();java.io.ByteArrayOutputStream bytes=new java.io.ByteArrayOutputStream();image.compress(android.graphics.Bitmap.CompressFormat.PNG,100,bytes);image.recycle();export(name,bytes.toByteArray(),"image/png",".png");export(name,nodes(getUiAutomation().getRootInActiveWindow()).getBytes(java.nio.charset.StandardCharsets.UTF_8),"text/plain",".txt");}
 private void desc(String description)throws Exception{AccessibilityNodeInfo n=getUiAutomation().getRootInActiveWindow();java.util.ArrayDeque<AccessibilityNodeInfo> q=new java.util.ArrayDeque<>();q.add(n);while(!q.isEmpty()){n=q.removeFirst();if(description.contentEquals(n.getContentDescription()==null?"":n.getContentDescription())){while(!n.isClickable())n=n.getParent();n.performAction(AccessibilityNodeInfo.ACTION_CLICK);SystemClock.sleep(300);return;}for(int i=0;i<n.getChildCount();i++)if(n.getChild(i)!=null)q.add(n.getChild(i));}throw new IllegalStateException("Missing description "+description);}
 private android.content.SharedPreferences prefs;private java.util.Map<String,?> saved;
 private void restore(){if(saved==null)return;if(activity!=null&&!activity.isFinishing()){runOnMainSync(()->activity.finish());waitForIdleSync();}android.content.SharedPreferences.Editor e=prefs.edit().clear();for(java.util.Map.Entry<String,?> entry:saved.entrySet()){String k=entry.getKey();Object v=entry.getValue();if(v instanceof String)e.putString(k,(String)v);else if(v instanceof Boolean)e.putBoolean(k,(Boolean)v);else if(v instanceof Integer)e.putInt(k,(Integer)v);else if(v instanceof Long)e.putLong(k,(Long)v);else if(v instanceof Float)e.putFloat(k,(Float)v);else if(v instanceof java.util.Set)e.putStringSet(k,(java.util.Set<String>)v);}e.commit();saved=null;}

 private android.graphics.Rect bounds(String label)throws Exception{AccessibilityNodeInfo n=find(label,false,getUiAutomation().getRootInActiveWindow());if(n==null)throw new IllegalStateException("Missing "+label);while(!n.isFocusable())n=n.getParent();android.graphics.Rect r=new android.graphics.Rect();n.getBoundsInScreen(r);return r;}
 private void sameBounds(String label,android.graphics.Rect before)throws Exception{android.graphics.Rect after=bounds(label);if(Math.abs(after.width()-before.width())>1||Math.abs(after.height()-before.height())>1||Math.abs(after.left-before.left)>1||Math.abs(after.top-before.top)>1)throw new IllegalStateException("Focus scaled/moved "+label+" "+before+" → "+after);}
 private void motion(int source,int action,long down,float x,float y,int button){android.view.MotionEvent.PointerProperties prop=new android.view.MotionEvent.PointerProperties();prop.id=0;prop.toolType=source==android.view.InputDevice.SOURCE_MOUSE?3:1;android.view.MotionEvent.PointerCoords coord=new android.view.MotionEvent.PointerCoords();coord.x=x;coord.y=y;coord.pressure=action==1?0:1;coord.size=1;android.view.MotionEvent e=android.view.MotionEvent.obtain(down,SystemClock.uptimeMillis(),action,1,new android.view.MotionEvent.PointerProperties[]{prop},new android.view.MotionEvent.PointerCoords[]{coord},0,action==1?0:button,1,1,0,0,source,0);if(!getUiAutomation().injectInputEvent(e,true))throw new IllegalStateException("Inject pointer");e.recycle();}
 private void tap(int source,float x,float y,long hold,int button){long now=SystemClock.uptimeMillis();motion(source,0,now,x,y,button);SystemClock.sleep(hold);motion(source,1,now,x,y,button);waitForIdleSync();SystemClock.sleep(200);}
 private void drag(int source,float x,float y,float tx,float ty){long now=SystemClock.uptimeMillis();motion(source,0,now,x,y,1);for(int i=1;i<=8;i++){SystemClock.sleep(20);motion(source,2,now,x+(tx-x)*i/8,y+(ty-y)*i/8,1);}motion(source,1,now,tx,ty,1);waitForIdleSync();SystemClock.sleep(300);}
 private boolean descExists(String label,AccessibilityNodeInfo n){if(n==null)return false;if(label.contentEquals(n.getContentDescription()==null?"":n.getContentDescription()))return true;for(int i=0;i<n.getChildCount();i++)if(descExists(label,n.getChild(i)))return true;return false;}

 private boolean small;
 private AccessibilityNodeInfo editable(AccessibilityNodeInfo n){if(n==null)return null;n.refresh();if(n.isEditable())return n;for(int i=0;i<n.getChildCount();i++){AccessibilityNodeInfo r=editable(n.getChild(i));if(r!=null)return r;}return null;}
 private void finding(String id,String detail){Bundle b=new Bundle();b.putString("stream","FINDING "+id+" "+detail+"\n");sendStatus(0,b);}
 private void titleMetrics(AccessibilityNodeInfo n,StringBuilder out){if(n==null)return;android.graphics.Rect r=new android.graphics.Rect();n.getBoundsInScreen(r);if(n.getText()!=null)out.append(n.getText()).append(" bounds=").append(r).append(" width=").append(r.width()).append('\n');for(int i=0;i<n.getChildCount();i++)titleMetrics(n.getChild(i),out);}
 @Override public void onStart(){try{
  small=getArgumentsMode;
  int touch=android.view.InputDevice.SOURCE_TOUCHSCREEN;
  prefs=getTargetContext().getSharedPreferences("nexttv",0);saved=prefs.getAll();prefs.edit().putString("selected_group","").putBoolean("previews",false).putBoolean("auto_update",false).putBoolean("auto_update_epg",false).putBoolean("grid_mode",true).commit();launch();
  if(!small){
   focus("设置");click("节目单地址");text("保存并更新");AccessibilityNodeInfo f=find("XMLTV 节目单地址",false,getUiAutomation().getRootInActiveWindow());while(!f.isClickable())f=f.getParent();android.graphics.Rect fr=new android.graphics.Rect();f.getBoundsInScreen(fr);tap(touch,fr.exactCenterX(),fr.exactCenterY(),60,1);await("editable field",()->editable(getUiAutomation().getRootInActiveWindow())!=null);Bundle value=new Bundle();value.putCharSequence(AccessibilityNodeInfo.ACTION_ARGUMENT_SET_TEXT_CHARSEQUENCE,"");if(!editable(getUiAutomation().getRootInActiveWindow()).performAction(AccessibilityNodeInfo.ACTION_SET_TEXT,value))throw new IllegalStateException("clear draft");key(KeyEvent.KEYCODE_ESCAPE);click("保存并更新");await("EPG cleared",()->!tree().contains("保存并更新"));if(!prefs.getString("manual_epg_url","bad").isEmpty())throw new IllegalStateException("Manual EPG not cleared");record("fixed-epg-clear");pass("P1-04 empty manual EPG saves and returns to embedded guide");focus("频道");
  }
  click("CCTV1综合");SystemClock.sleep(1500);key(KeyEvent.KEYCODE_ENTER);text("央视");key(KeyEvent.KEYCODE_DPAD_RIGHT);text("日期");
  if(!small){
   android.graphics.Rect before=new android.graphics.Rect();focused(getUiAutomation().getRootInActiveWindow()).getBoundsInScreen(before);String original=focus();drag(touch,160,430,160,250);android.graphics.Rect after=new android.graphics.Rect();focused(getUiAutomation().getRootInActiveWindow()).getBoundsInScreen(after);if(after.left>350)throw new IllegalStateException("Drag targeted other column "+after);pass("P2-01 drag targets origin channel column");record("fixed-drag-origin");key(KeyEvent.KEYCODE_ESCAPE);key(KeyEvent.KEYCODE_DPAD_DOWN);text("CCTV2财经");key(KeyEvent.KEYCODE_ESCAPE);key(KeyEvent.KEYCODE_BACK);text("再按一次退出播放");key(KeyEvent.KEYCODE_BACK);text("频道分类：");SystemClock.sleep(500);if(!focus().contains("CCTV2财经"))throw new IllegalStateException("Wrong exit focus "+focus());pass("P1-01 zap exit restores actual channel");record("fixed-exit-focus");click("CCTV1综合");SystemClock.sleep(1500);key(KeyEvent.KEYCODE_MENU);text("适应画面");text("音轨");text("主页");if(tree().contains("选台"))throw new IllegalStateException("Old select-channel shortcut");focus("适应画面");key(KeyEvent.KEYCODE_ENTER);text("裁切填充");key(KeyEvent.KEYCODE_ENTER);text("拉伸全屏");key(KeyEvent.KEYCODE_ENTER);text("适应画面");record("fixed-player-actions");pass("quick actions aspect cycles, audio and Home present, no select-channel button");click("主页");text("频道分类：");focus("设置");android.graphics.Rect sr=bounds("节目单地址");if(sr.left<500)throw new IllegalStateException("Settings is not right half "+sr);record("fixed-settings-half");pass("settings occupies right half");
  }else{
   StringBuilder metrics=new StringBuilder();titleMetrics(focused(getUiAutomation().getRootInActiveWindow()),metrics);if(metrics.toString().split("\n").length<3)throw new IllegalStateException("Missing programme title "+metrics);pass("P1-05 small-screen programme retains title/time/status");record("audit-small-epg-title-width");key(KeyEvent.KEYCODE_ESCAPE);key(KeyEvent.KEYCODE_MENU);text("适应画面");record("audit-small-player-info");key(KeyEvent.KEYCODE_ESCAPE);key(KeyEvent.KEYCODE_BACK);text("再按一次退出播放");key(KeyEvent.KEYCODE_BACK);focus("设置");record("audit-small-settings");
  }
  restore();Bundle b=new Bundle();b.putString("stream","Subscription fixes completed\n");finish(Activity.RESULT_OK,b);
 }catch(Throwable t){restore();Bundle b=new Bundle();b.putString("stream",android.util.Log.getStackTraceString(t));finish(Activity.RESULT_CANCELED,b);}}
}
